WITH itineraries AS (SELECT FlightDate, count() AS hops, arrayStringConcat(arrayConcat(arraySort((x, t) -> t, groupArray(OriginCode), groupArray(assumeNotNull(CRSDepTime))), [argMax(DestCode, assumeNotNull(CRSDepTime))]), '-') AS Route, arrayDistinct(groupArray(OriginState)) AS states_covered FROM ontime.fact_ontime WHERE Tail_Number != '' AND Cancelled = 0 GROUP BY FlightDate, Tail_Number, Flight_Number_Reporting_Airline HAVING hops = 8), route_stats AS (SELECT Route, count() AS occurrences, any(states_covered) AS states_sample FROM itineraries GROUP BY Route) SELECT Route, occurrences, length(states_sample) AS state_count, states_sample FROM route_stats ORDER BY occurrences DESC LIMIT 10
